"""Bounded real-browser development check; the first exact correction triggers one labelled software double."""
import argparse,asyncio,base64,hashlib,json,os,subprocess,time
from datetime import datetime,timezone
from contextvars import ContextVar
from pathlib import Path

ROOT=Path('/Users/honghuy127/GitHub/meta-vibe-coding')
def sha(raw):return hashlib.sha256(raw).hexdigest()
def utc():return datetime.now(timezone.utc).isoformat()
def exclusive(path,value):
 with path.open('x') as f:json.dump(value,f,ensure_ascii=False,indent=2);f.write('\n')

def main():
 parser=argparse.ArgumentParser();parser.add_argument('--plan',type=Path,required=True);parser.add_argument('--approval',type=Path,required=True);args=parser.parse_args()
 plan=json.loads(args.plan.read_text());approval=json.loads(args.approval.read_text());run=Path(plan['execution_directory'])
 assert plan['limits']=={'assessment_attempts':5,'native_calls':4,'synthetic_faults':1,'clarification_questions':5,'request_seconds':300,'session_seconds':1800},'Reviewed limits differ'
 assert approval['verdict']=='pass' and approval['plan_sha256']==sha(args.plan.read_bytes()) and approval['harness_sha256']==sha(Path(__file__).read_bytes())
 assert approval.get('journal_sha256') is None and not (run/'journal.jsonl').exists()
 for key in ['ANTHROPIC_API_KEY','ANTHROPIC_AUTH_TOKEN','MVC_BACKEND']:os.environ.pop(key,None)
 os.environ.update(MVC_AGENT='claude',MVC_AGENT_MODEL=plan['agent']['model'],MVC_ENABLE_AGENT='1',MVC_AGENT_ENV='',
  MVC_AGENT_MAX_CALLS=str(plan['limits']['native_calls']),MVC_REQUEST_TIMEOUT_SECONDS='300',MVC_SESSION_TIMEOUT_SECONDS='1800')
 from meta_vibe_coding import agents,evaluation
 from meta_vibe_coding.app import create_app
 from meta_vibe_coding.core import FlowError
 from starlette.responses import Response,JSONResponse
 import uvicorn
 def verify():
  evaluation.verify_checkout(ROOT)
  frozen=plan['frozen_runtime']
  assert evaluation.source_snapshot(ROOT)==frozen['source_snapshot'],'Source drift'
  assert agents.PROMPT==frozen['wrapper_prompt'] and json.loads(agents.SCHEMA)==frozen['wrapper_schema'],'Imported contract drift'
  assert sha((ROOT/'requirements.lock').read_bytes())==frozen['requirements_lock_sha256'],'Dependency lock drift'
  assert sha(Path(__file__).read_bytes())==plan['harness_sha256'],'Harness drift'
  assert sha(args.plan.read_bytes())==approval['plan_sha256'],'Plan drift'
 verify();env=agents.agent_environment('claude');assert not {'ANTHROPIC_API_KEY','ANTHROPIC_AUTH_TOKEN'}&env.keys()
 status=subprocess.run(['claude','auth','status'],env=env,capture_output=True,text=True,check=True,timeout=25)
 auth=json.loads(status.stdout);assert auth.get('loggedIn') is True and auth.get('authMethod')=='claude.ai'
 native=agents.CodingAgent();version=subprocess.run([native.binary,'--version'],env=env,capture_output=True,text=True,check=True,timeout=10).stdout.strip()
 runtime={'agent_version':version,'agent_binary_sha256':sha(Path(native.binary).resolve().read_bytes()),'native_login_first_party':True}
 assert runtime['agent_version']==plan['agent']['version'] and runtime['agent_binary_sha256']==plan['agent']['binary_sha256']
 run.mkdir(parents=True,exist_ok=True)
 exclusive(run/'run.claim',{'kind':'bounded-live-browser-development','plan_sha256':approval['plan_sha256'],'assessment_attempt_cap':5,'native_call_cap':4,'synthetic_failure_count':1,'authority':plan['authority']})
 exclusive(run/'manifest.json',{'kind':'bounded-live-browser-development','started_at_utc':utc(),'plan_sha256':approval['plan_sha256'],'harness_sha256':plan['harness_sha256'],'approval':approval,'harness_source':Path(__file__).read_text(),**runtime})
 journal=(run/'journal.jsonl').open('x')
 def event(kind,**data):
  journal.write(json.dumps({'type':kind,'at_utc':utc(),**data},ensure_ascii=False)+'\n');journal.flush();os.fsync(journal.fileno())
 original_cli=agents.run_cli;native_starts=0
 active_request_id=ContextVar('ui_verification_request_id',default=None)
 synthetic_message='UI verification: scripted timeout. Your answers are retained; retry this simulated failed step.'
 async def recorded_cli(argv,**kwargs):
  nonlocal native_starts
  if '--help' in argv or '--version' in argv:return await original_cli(argv,**kwargs)
  try:
   verify();assert sha(Path(native.binary).resolve().read_bytes())==plan['agent']['binary_sha256'],'Native binary drift'
  except (AssertionError,ValueError) as exc:
   event('verification_stop',reason='Source, contract or native binary drift before CLI startup.');raise FlowError('disabled','Verification snapshot changed; stop and retain evidence.') from exc
  assert native_starts<4;native_starts+=1;number=native_starts;streams={};began=time.monotonic()
  event('native_started',number=number,argv=['claude',*argv[1:]],stdin=kwargs['content'],stdin_sha256=sha(kwargs['content'].encode()),timeout_seconds=kwargs['timeout'])
  def capture(stdout,stderr,code):
   streams['returncode']=code
   for name,raw in [('stdout',stdout),('stderr',stderr)]:
    streams[name+'_sha256']=sha(raw)
    try:streams[name]=raw.decode()
    except UnicodeError:streams[name+'_base64']=base64.b64encode(raw).decode()
  error=None
  try:return await original_cli(argv,**{**kwargs,'capture':capture})
  except Exception as exc:
   error={'type':type(exc).__name__};raise
  finally:event('native_finished',number=number,elapsed_seconds=time.monotonic()-began,error=error,streams=streams)
 agents.run_cli=recorded_cli
 class OneFault:
  agent='claude';model=native.model;enabled=True;max_calls=4
  def __init__(self):self.attempts=0;self.fault_used=False;self.synthetic_request_id=None;self.blocked=False
  async def assess(self,state,provisional):
   verify()
   if self.blocked:raise FlowError('disabled','Verification stopped after a real native/state failure; original evidence is retained.')
   self.attempts+=1
   if self.attempts>5:raise FlowError('limit','Verification assessment allowance reached.')
   event('assessment_attempt',number=self.attempts,state_revision=state.revision,request_provisional=provisional)
   if not self.fault_used and state.turns and state.turns[-1].text==plan['scenario']['correction']:
    self.synthetic_request_id=active_request_id.get();self.fault_used=True
    event('synthetic_failure',assessment_attempt=self.attempts,request_id=self.synthetic_request_id,failure_code='timeout',native_started=False,reason='Declared one-off software recovery double, not a provider failure.')
    raise FlowError('timeout',synthetic_message)
   return await native.assess(state,provisional)
 adapter=OneFault();app=create_app(adapter)
 @app.middleware('http')
 async def record_http(request,call_next):
  path=request.url.path
  if path.startswith('/api/'):
   try:verify()
   except (AssertionError,ValueError):
    adapter.blocked=True;event('source_drift',path=path);return JSONResponse({'error':'Verification source changed; stop.'},status_code=503)
  body=None
  if request.method=='POST':
   try:body=json.loads(await request.body())
   except (ValueError,UnicodeError):body=None
  native_before=native_starts
  token=active_request_id.set(body.get('request_id')) if path=='/api/advance' and isinstance(body,dict) else None
  try:response=await call_next(request)
  except Exception as exc:
   adapter.blocked=True;event('verification_stop',reason='Unexpected application failure; no native retry permitted.',error_type=type(exc).__name__)
   return JSONResponse({'error':'Verification stopped after an unexpected application failure.'},status_code=500)
  finally:
   if token is not None:active_request_id.reset(token)
  if path.startswith('/api/'):
   raw=b''.join([chunk async for chunk in response.body_iterator]);data=json.loads(raw)
   event('http',path=path,method=request.method,request=body,status=response.status_code,response=data)
   if path=='/api/advance' and data.get('error'):
    expected_synthetic=(response.status_code==200 and adapter.synthetic_request_id is not None
      and isinstance(body,dict) and data.get('request_id')==body.get('request_id')==adapter.synthetic_request_id
      and data['error']=={'code':'timeout','message':synthetic_message} and native_starts==native_before)
    if not expected_synthetic:
     adapter.blocked=True;event('verification_stop',reason='Real native/state failure; no native retry permitted.',error=data['error'])
   return Response(raw,status_code=response.status_code,headers=dict(response.headers),media_type=response.media_type)
  return response
 event('run_started',manifest_sha256=sha((run/'manifest.json').read_bytes()))
 try:uvicorn.run(app,host='127.0.0.1',port=plan['port'],access_log=False,log_level='warning')
 finally:
  event('run_stopped',assessment_attempts=adapter.attempts,native_starts=native_starts,synthetic_failure_used=adapter.fault_used,blocked_after_real_error=adapter.blocked);journal.close()
if __name__=='__main__':main()

