const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const run = '/tmp/mvc-t035-next-ui-2026-11-05';
const downloaded = process.argv[2];
if (!downloaded) throw new Error('Supply the actual browser download path.');
const events = fs.readFileSync(path.join(run, 'journal.jsonl'), 'utf8').trim().split('\n').map(JSON.parse);
const advances = events.filter(e => e.type === 'http' && e.path === '/api/advance');
const state = advances.at(-1)?.response.state;
if (!state?.assessment || advances.at(-1).response.error) throw new Error('No current successful assessment.');
const exported = events.filter(e => e.type === 'http' && e.path === '/api/export' && e.status === 200).at(-1)?.response;
if (!exported || exported.revision !== state.revision || exported.raw_intent !== state.raw_intent) throw new Error('Current export missing.');
const expected = Buffer.from(JSON.stringify(exported, null, 2));
const actual = fs.readFileSync(downloaded);
if (!actual.equals(expected)) throw new Error('Downloaded bytes differ from production export serialization.');
const parsed = JSON.parse(actual);
if (parsed.revision !== state.revision) throw new Error('Revision mismatch.');
fs.copyFileSync(downloaded, path.join(run, 'downloaded-brief.json'), fs.constants.COPYFILE_EXCL);
const proof = {kind:'actual-browser-download-comparison', source_basename:path.basename(downloaded), bytes:actual.length, sha256:crypto.createHash('sha256').update(actual).digest('hex'), byte_match:true, json_match:true, revision:parsed.revision, scope:'Verifies already executed browser download bytes; performs no UI or native-model call.'};
fs.writeFileSync(path.join(run,'download-proof.json'), JSON.stringify(proof,null,2)+'\n', {flag:'wx'});
process.stdout.write(JSON.stringify(proof)+'\n');

